// JAH demo program — EMD determinant coder
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function determinant(problem, conscious, breathing){
  if(problem==='cardiac'&&!breathing) return '9-E-1';
  if(problem==='cardiac'&&breathing) return '9-C-1';
  if(problem==='choking'&&!breathing) return '11-E-1';
  if(problem==='bleeding') return conscious?'21-B-1':'21-D-1';
  return '32-B-1';
}
check("cardiac arrest, not breathing", determinant('cardiac',false,false), "9-E-1");
check("cardiac, breathing", determinant('cardiac',true,true), "9-C-1");
check("choking, not breathing", determinant('choking',true,false), "11-E-1");
check("severe bleeding, unconscious", determinant('bleeding',false,true), "21-D-1");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

// JAH demo program — START triage sieve
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function triage(resp, pulse, mental){
  if(resp===0) return 'EXPECTANT';
  if(resp>30) return 'IMMEDIATE';
  if(pulse==='absent'||pulse==='delayed') return 'IMMEDIATE';
  if(mental!=='follows-commands') return 'IMMEDIATE';
